  "claims": [
    {
      "claim": "Pethidine, a 4-phenylpiperidine opioid structurally related to the query's fentanyl-like piperidine amide, showed absolute oral bioavailability of 0.80 ± 0.15 in cirrhotic patients, supporting F ≥ 20%.",
      "card_ids": ["C07", "C14"]
    },
    {
      "claim": "Encainide, a piperidine-containing anilide, showed oral bioavailability of 76–78% in cirrhotic patients, supporting high F for piperidine amide-type drugs.",
      "card_ids": ["C03", "C06", "C12"]
    },
    {
      "claim": "Meptazinol, an opioid, had absolute bioavailability of 27.9 ± 5.3% in cirrhosis, still above the 20% threshold.",
      "card_ids": ["C04"]
    },
    {
      "claim": "Ziprasidone, a heteroaryl piperazine with a thiophene-like benzisothiazole, had absolute bioavailability of approximately 59–60% when given with a high-fat meal.",
      "card_ids": ["C05", "C10", "C13"]
    },
    {
      "claim": "Thiophene-containing drugs tenidap, suprofen, and R406 had absolute bioavailability values of 85%, 92.2%, and 55%, respectively, all supporting F ≥ 20%.",
      "card_ids": ["C09", "C11", "C15"]
    },
    {
      "claim": "Additional positive oral bioavailability records include SAHA 43% fasted, FK788 55%, and PEMA at least 80%, none of which suggest F < 20%.",
      "card_ids": ["C01", "C02", "C08", "C16"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C01", "C02", "C03", "C04", "C05", "C06", "C07", "C08", "C09", "C10", "C11", "C12", "C13", "C14", "C15", "C16"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule itself.",
    "Most relevant records are from cirrhosis or fed/fasted conditions, while the query condition is unspecified; absolute F may differ in a healthy, fasted setting.",
    "No experimental solubility, permeability, or first-pass metabolism data are available for the query.",
    "Structural differences from the closest contexts, especially the methoxymethyl and thiophene substituents, could alter metabolic clearance and absorption."
  ],
  "decision_summary": "All L1 gold records show absolute oral bioavailability at or above 27.9%, with most values above 50%, and the most transferable contexts (pethidine, encainide, meptazinol, ziprasidone, and thiophene-containing drugs) support F ≥ 20% for this fentanyl-like piperidine amide. No affirmative threshold-relevant evidence supports F < 20%, so the prediction is high with moderate confidence."
}

